d<-read.csv('work/stage6_foxp2_susie_aligned.csv');p<-nrow(d);g<-matrix(readBin('work/stage6_foxp2_reference_genotypes_float64.bin','double',n=p*503,size=8,endian='little'),503,p);R<-cor(g);ij<-which(upper.tri(R)&abs(R)>.98,arr.ind=TRUE);res<-list()
for (name in c('mvp_z_anchor','hfrs_z_anchor')){z<-d[[name]];delta<-abs(z[ij[,1]]-sign(R[ij])*z[ij[,2]]);res[[length(res)+1]]<-data.frame(trait=name,n_snps=p,n_high_ld_pairs=length(delta),n_delta_gt2=sum(delta>2),n_delta_gt3=sum(delta>3),max_abs_delta=max(delta));idx<-order(delta,decreasing=TRUE)[1:min(20,length(delta))];pair<-data.frame(variant1=d$rs[ij[idx,1]],variant2=d$rs[ij[idx,2]],r=R[ij[idx,,drop=FALSE]],z1=z[ij[idx,1]],z2=z[ij[idx,2]],difference=delta[idx]);write.csv(pair,paste0('outputs/stage6_foxp2_',name,'_high_ld_differences.csv'),row.names=FALSE)}
write.csv(do.call(rbind,res),'outputs/stage6_foxp2_high_ld_diagnostic.csv',row.names=FALSE);print(do.call(rbind,res))
